/* Tirupati Express - Responsive Slides (lightweight) */
(function ($) {
  $.fn.responsiveSlides = function (options) {
    var opts = $.extend(
      { auto: true, nav: false, pager: true, speed: 500, namespace: "callbacks", timeout: 4000 },
      options
    );

    return this.each(function () {
      var $ul = $(this);
      var $items = $ul.children("li");
      if (!$items.length) return;

      var index = 0;
      var total = $items.length;
      var timer = null;

      $items.hide().eq(0).show();

      // Pager dots
      if (opts.pager) {
        var $pager = $('<div class="' + opts.namespace + '_buttons"></div>');
        for (var i = 0; i < total; i++) {
          $("<a href='#' class='" + (i === 0 ? "callbacks_here" : "") + "'></a>")
            .data("i", i)
            .appendTo($pager);
        }
        $ul.after($pager);
        $pager.on("click", "a", function (e) {
          e.preventDefault();
          goTo($(this).data("i"));
        });
      }

      // Nav arrows
      if (opts.nav) {
        var $navPrev = $("<a href='#' class='" + opts.namespace + "_nav " + opts.namespace + "_nav_prev'>&#10094;</a>");
        var $navNext = $("<a href='#' class='" + opts.namespace + "_nav " + opts.namespace + "_nav_next'>&#10095;</a>");
        $ul.parent().css("position", "relative").append($navPrev).append($navNext);
        $navPrev.on("click", function (e) { e.preventDefault(); goTo(index - 1); });
        $navNext.on("click", function (e) { e.preventDefault(); goTo(index + 1); });
      }

      function goTo(i) {
        i = (i + total) % total;
        if (i === index) return;
        $items.eq(index).fadeOut(opts.speed);
        $items.eq(i).fadeIn(opts.speed);
        index = i;
        if (opts.pager) {
          $ul.next("." + opts.namespace + "_buttons").find("a")
            .removeClass("callbacks_here").eq(index).addClass("callbacks_here");
        }
        restart();
      }

      function restart() {
        if (timer) clearInterval(timer);
        if (opts.auto) {
          timer = setInterval(function () { goTo(index + 1); }, opts.timeout);
        }
      }

      restart();
    });
  };
})(jQuery);
